package luma.ui;
public class PressMotionTest {
 public static void main(String[] a){PressMotion p=new PressMotion();if(p.active())throw new AssertionError();p.down(30,40);float first=p.scaleY(PressMotion.WATER);for(int i=0;i<3;i++)p.step(.05f);if(p.scaleY(PressMotion.WATER)>=first||p.scaleX(PressMotion.WATER)<=1)throw new AssertionError("water press");if(p.scaleX(PressMotion.SOFT)>=1||p.scaleY(PressMotion.SOFT)>=1)throw new AssertionError("soft press");float before=p.scaleY(PressMotion.WATER);p.release();if(Math.abs(before-p.scaleY(PressMotion.WATER))>.0001)throw new AssertionError("release continuity");boolean overshoot=false;for(int i=0;i<40;i++){p.step(.025f);if(p.scaleY(PressMotion.WATER)>1)overshoot=true;}if(p.active()||!overshoot||p.scaleY(PressMotion.WATER)!=1)throw new AssertionError("spring settling");p.down(1,1);p.cancel();if(p.active()||p.scaleX(PressMotion.OFF)!=1)throw new AssertionError("cancel/off");System.out.println("Independent button press motion tests passed");}
}
